from pathlib import Path
import json,shutil
O=Path('doc/space/randomness-dna-2026-09-16');S=Path('doc/research/possible-bodies');(S/'randomness-dna').mkdir(exist_ok=True);checks=[]
for hall,token in [('Random_Definition','textile_comparison'),('Random_Mushrooms','couture_comparison')]:
 d=json.loads((O/(hall+'-runtime.json')).read_text(encoding='utf-8'));assert not d['failures'];checks+=d['checks'];assert 'SCRIPT ERROR' not in (O/(hall+'-process.log')).read_text(encoding='utf-8')
 shutil.copy2(O/(hall+'-'+token+'.png'),S/'randomness-dna'/(token+'.png'))
assert all(c['passed'] for c in checks)
